import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0
    orders_info = {}  # id -> dict with side, price, qty, seq, active

    def add_order(oid, side, price, qty, seq):
        orders_info[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def pop_valid_top(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            info = orders_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return oid, info
        return None, None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info and info['active']:
                info['active'] = False
            continue

        oid = order[1]
        side = order[2]
        seq_counter += 1
        seq = seq_counter

        if typ == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        remaining = qty
        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            other_id, other_info = pop_valid_top(opp_heap)
            if other_id is None:
                break

            if typ != 'market':
                if side == 'buy' and other_info['price'] > price:
                    break
                if side == 'sell' and other_info['price'] < price:
                    break

            trade_qty = min(remaining, other_info['qty'])
            trade_price = other_info['price']

            if side == 'buy':
                trades.append([oid, other_id, trade_price, trade_qty])
            else:
                trades.append([other_id, oid, trade_price, trade_qty])

            other_info['qty'] -= trade_qty
            remaining -= trade_qty

            if other_info['qty'] == 0:
                other_info['active'] = False
                heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            add_order(oid, side, price, remaining, seq)
        # ioc/market remainder discarded

    return trades

